          "id": "production_year_021",
          "sceneId": "production_year",
          "type": "chat",
          "time": "21:51",
          "speaker": "mizuha",
          "speakerLabel": "🌱 みず 🌱",
          "text": "原因を一つに決めない表示も欲しいですわ。"
