          "id": "production_year_053",
          "sceneId": "production_year",
          "type": "chat",
          "time": "22:38",
          "speaker": "sakuya",
          "speakerLabel": "🌸 saku 🌸",
          "text": "色だけ見たら、気温そのものだと思う。"
