          "id": "production_year_056",
          "sceneId": "production_year",
          "type": "chat",
          "time": "22:47",
          "speaker": "mizuha",
          "speakerLabel": "🌱 みず 🌱",
          "text": "元の2つの値も、すぐ開けるようにしましょ。"
